import { type ComponentProps, type ReactNode } from "react";
import { DatePicker as Root, DateRangePicker as RangeRoot, Group, Label, Text, FieldError, Dialog } from "react-aria-components";
import { DateField } from "../date-field/index";
import { Button } from "../button/index";
import { Calendar } from "../calendar/index";
import { Popover } from "../popover/index";
type Naming = { label: ReactNode; triggerLabel: string; description?: ReactNode; errorMessage?: ReactNode };
export function DatePicker({ label, triggerLabel, description, errorMessage, ...props }: Omit<ComponentProps<typeof Root>, "children"> & Naming) {
 return <Root {...props}><Label>{label}</Label><Group><DateField label={null} pickerContext /><Button aria-label={triggerLabel}>{triggerLabel}</Button></Group>{description ? <Text slot="description">{description}</Text> : null}<FieldError>{errorMessage}</FieldError><Popover><Dialog><Calendar selection="single" /></Dialog></Popover></Root>;
}
export function DateRangePicker({ label, startLabel, endLabel, triggerLabel, description, errorMessage, ...props }: Omit<ComponentProps<typeof RangeRoot>, "children"> & Naming & { startLabel: ReactNode; endLabel: ReactNode }) {
 return <RangeRoot {...props}><Label>{label}</Label><Group><DateField slot="start" label={startLabel} pickerContext /><DateField slot="end" label={endLabel} pickerContext /><Button aria-label={triggerLabel}>{triggerLabel}</Button></Group>{description ? <Text slot="description">{description}</Text> : null}<FieldError>{errorMessage}</FieldError><Popover><Dialog><Calendar selection="range" /></Dialog></Popover></RangeRoot>;
}
